```json
{
  "name": "produce_and_execute_r",
  "arguments": {
    "rscript": "# Load required libraries
library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Load metadata files into separate objects
wave_one <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t")
wave_two <- read_delim("data/input/wave_two_lsype_young_person_2020.tab", delim = "\t")
wave_three <- read_delim("data/input/wave_three_lsype_family_background_2020.tab", delim = "\t")
wave_four <- read_delim("data/input/wave_four_lsype_family_background_2020.tab", delim = "\t")

# Merge datasets using full_join by NSID
merged_data <- full_join(
  full_join(wave_one, wave_two, by = "NSID"), 
  full_join(wave_three, wave_four, by = "NSID"), 
  by = "NSID"
)

# Define the mapping for missing values based on the additional requirements
missing_mapping <- list(
  "-999" = -3, "-998" = -2, "-997" = -2, "-995" = -2, "-99" = -3, "-92" = -9, "-91" = -1, "-1" = -8
)

# Function to map missing values
map_missing <- function(x) {
  if (is.numeric(x)) {
    x <- as.character(x)
    if (x %in% names(missing_mapping)) {
      return(missing_mapping[[x]])
    } else {
      return(x)
    }
  } else {
    return(x)
  }
}

# Apply missing value mapping to each source variable
merged_data <- merged_data %>%
  mutate(
    W1englangYP = map_missing(W1englangYP),
    W2EnglangYP = map_missing(W2EnglangYP),
    W3englangHH = map_missing(W3englangHH),
    W4EngLangHH = map_missing(W4EngLangHH)
  )

# Create a function to derive the consolidated 'lang' variable
derive_lang <- function(data) {
  data <- data %>%
    mutate(
      lang = coalesce(
        ifelse(W1englangYP %in% 1:4, W1englangYP, NA),
        ifelse(W2EnglangYP %in% 1:4, W2EnglangYP, NA),
        ifelse(W3englangHH %in% 1:4, W3englangHH, NA),
        ifelse(W4EngLangHH %in% 1:4, W4EngLangHH, NA),
        -3
      )
    )

  # Ensure the variable is numeric and create labels
  data$lang <- as.numeric(data$lang)

  # Create factor with labels
  labels <- c("1" = "English only", "2" = "English first/main and speaks other languages", 
              "3" = "No, another language is first/main", "4" = "Bilingual")

  # Define missing value labels
  missing_labels <- c("-9" = "Refusal", "-8" = "Don't know", "-7" = "Prefer not to say", 
                      "-3" = "Not asked/interviewed", "-2" = "Schedule not applicable", "-1" = "Not applicable")

  # Create labelled factor
  lang_lab <- labelled(data$lang, labels = labels)
  lang_lab <- labelled::labelled(lang_lab, labels = c(missing_labels, labels))

  return(lang_lab)
}

# Derive the 'lang' variable
merged_data <- derive_lang(merged_data)

# Select only the ID and the final derived variable
final_data <- merged_data %>%
  select(NSID, lang)

# Write the final cleaned data to CSV
write_csv(final_data, "data/output/cleaned_data.csv")"
  }
}
```

